fun isIdempotent(method: String, hasKey: Boolean) =
    method in setOf("GET", "HEAD", "OPTIONS", "TRACE", "PUT", "DELETE") || (method == "POST" && hasKey)

fun mayRetry(method: String, hasKey: Boolean, outcome: Outcome): Boolean = when (outcome) {
    Outcome.ConnectRefused, Outcome.ConnectTimeout -> true            // never sent
    Outcome.Reset, Outcome.ReadTimeout -> isIdempotent(method, hasKey)  // maybe processed
    is Outcome.Status -> outcome.code in setOf(429, 502, 503, 504) && isIdempotent(method, hasKey)
}

fun backoffMs(retry: Int, random: () -> Double = Math::random): Long {
    val ceiling = minOf(2_000L, 100L shl (retry - 1).coerceAtMost(30))  // 100, 200, 400 ... 2,000
    return (random() * ceiling).toLong()                                // anywhere below it
}

// Idle timeouts, shortest first: client pool < load balancer < backend server.
